INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT156-S4-Q22$batch11$, 156, 4, 22, $batch11$Sufficient Assumption$batch11$, $batch11$An effective acting performance does not call the audience’s attention to the fact that it is a performance. That would make it more difficult for the audience to empathize with the character the actor is playing, and effective dramatic performances do not detract from the audience’s appreciation of a play.$batch11$, $batch11$The argument’s conclusion follows logically from the premises if which one of the following is assumed?$batch11$, $batch11$E$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q22$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$An audience will not completely appreciate a play unless all of the acting performances in the play are effective.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$As long as an acting performance does not call the audience’s attention to the fact that it is a performance, it will not detract from the audience’s appreciation of a play.$batch11$, $batch11$Reversed$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$If a performance by an actor in a play enhances the audience’s appreciation of the play, then the play as a whole is better as a result.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$An effective dramatic performance in a play will enhance the audience’s appreciation of the play.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$A dramatic performance that makes it more difficult for the audience to empathize with the actor’s character detracts from the audience’s appreciation of the play.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT156-S4-Q22$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$An effective acting performance doesn't call attention to the fact that it's a performance.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Calling attention to the performance makes it harder for the audience to empathize with the character. Effective performances don't detract from the audience's appreciation of a play.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$Chain it. Calls attention → harder to empathize. Effective → doesn't detract. The gap: harder to empathize → detracts. With that link: calls attention → harder to empathize → detracts → not effective.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Making empathy harder detracts from appreciation of the play.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT156-S4-Q22$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$This is about what a play needs, not what makes a single performance ineffective.$batch11$), ($batch11$B$batch11$, $batch11$Not calling attention → not detracting. We need calling attention → detracting.$batch11$), ($batch11$C$batch11$, $batch11$Enhancing appreciation never connects to calling attention.$batch11$), ($batch11$D$batch11$, $batch11$Enhancing appreciation isn't the same as not detracting, and nothing links it to calling attention.$batch11$), ($batch11$E$batch11$, $batch11$Calling attention makes empathy harder, which detracts from appreciation, which an effective performance never does.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT156-S4-Q22$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
